def reverse_create_events_for_existing_annotations(apps, schema_editor):
    AnnotationEvent = apps.get_model("annotation", "AnnotationEvent")
    KnowledgeBaseAnnotation = apps.get_model("annotation", "KnowledgeBaseAnnotation")
    LabelAnnotation = apps.get_model("annotation", "LabelAnnotation")

    MODEL_EVENT_TYPE_MAP = [
        (KnowledgeBaseAnnotation, "knowledgeBase"),
        (LabelAnnotation, "label"),
    ]

    for Model, event_type in MODEL_EVENT_TYPE_MAP:
        for annotation in Model.objects.all():
            created_event = (
                AnnotationEvent.objects.filter(
                    event_type=event_type,
                    annotation_id=annotation.pk,
                    action="created",
                )
                .order_by("-occurred_at")
                .first()
            )
            if created_event:
                annotation.created_at = created_event.occurred_at
                annotation.created_by = created_event.actor
                annotation.save(update_fields=["created_at", "created_by"])

            deleted_event = (
                AnnotationEvent.objects.filter(
                    event_type=event_type,
                    annotation_id=annotation.pk,
                    action="removed",
                )
                .order_by("-occurred_at")
                .first()
            )
            if deleted_event:
                annotation.removed_at = deleted_event.occurred_at
                annotation.removed_by = deleted_event.actor
                annotation.save(update_fields=["removed_at", "removed_by"])


